import{z as l,x as B,o as n,c as d,q as t,j as A,D as r,d as E,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"工具变量的深化：异质依从","description":"","frontmatter":{"title":"工具变量的深化：异质依从","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-iv-heterogeneous-compliers.md","filePath":"econ/pe-iv-heterogeneous-compliers.md","lastUpdated":1791413859000}'),m={name:"econ/pe-iv-heterogeneous-compliers.md"};function p(D,e,c,T,u,h){const s=B("Mermaid");return n(),d("div",null,[e[2]||(e[2]=t('<h1 id="工具变量的深化-异质依从" tabindex="-1">工具变量的深化：异质依从 <a class="header-anchor" href="#工具变量的深化-异质依从" aria-label="Permalink to &quot;工具变量的深化：异质依从&quot;">​</a></h1><div class="epigraph"><p>IV 回答的不是「处理的效果」，而是「工具撬动的那条边际上，依从者的效果」；换一个工具，就换了一个问题。</p><footer>—— Imbens and Angrist, Econometrica 1994；Angrist, Imbens and Rubin, JASA 1996；Heckman and Vytlacil, Econometrica 2005</footer></div><p><a href="/econ/pe-rdd-deep">上一课</a>把门槛上的证据钉牢，模糊断点只留了一句接口：门槛 IV 估计的是门槛邻域内依从者的效应。本课展开这个接口。主干<a href="/econ/iv-weak-instruments">工具变量与弱工具</a>钉了相关与排除、弱工具偏向 OLS；那里先用了常数 \\(\\beta\\)。本课在效应异质下把 IV 的估计对象拆开：谁在依从、Wald 比认得谁、以及这个数字能回答什么政策问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>让潜在处理状态随工具取值：\\(D_i(z)\\) 是「若工具定为 \\(z\\)，个体 \\(i\\) 是否被处理」。按 \\(D_i(1)\\) 与 \\(D_i(0)\\) 把人口劈成四层：两边都处理的 always-takers、两边都不处理的 never-takers、只在工具向上时处理的 compliers、反向的 defiers。<strong>单调性</strong> \\(D_i(1)\\ge D_i(0)\\) 排除 defiers 后，Wald 比 \\(\\mathrm{Cov}(Z,Y)/\\mathrm{Cov}(Z,D)\\) 识别的恰是依从者的平均处理效应（Imbens–Angrist 的 LATE）。这带来三个必须直面的问题。其一，LATE 是<strong>工具特定的</strong>：出生季度撬动的是「多读几个月书」的边际学生，距离大学的边际很远；换一个工具，撬动另一批人，数字不同。其二，排除在异质下读法更苛刻：Angrist–Imbens–Rubin 的假设结构要求工具对每层潜结果的作用只经处理状态传导，恰可识别时它仍不可检验。其三，依从者不可观测——你不知道谁被工具移动了——但他们的协变量画像可以恢复（Abadie 2003），这是 LATE 从一个数字变成一个群体的唯一途径。</p><p><span class="marginnote">直觉类比：把工具想成一张随机发放的优惠券。发不发都会买的是 always-takers，发了也不买的是 never-takers，见券才买的是 compliers，见券偏不买的是 defiers（被单调性排除）。IV 能度量的只有第三种人——券带来的销量变化全部发生在他们身上，前两种人对券毫无反应，数据里没有他们的效应信息。</span></p><p><span class="marginnote">Angrist–Krueger 的出生季度工具至今是好例子：它识别的只对「因义务教育约束多读了书」的人。对无论如何要读完高中的 never-takers，数据里没有任何关于他们的信息——份额小，则 Wald 比虽准，覆盖的人极少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报 LATE 时同时报四件：第一阶段（工具撬动处理率的幅度）、依从者份额（第一阶段本身就是它的估计）、依从者的协变量画像（Abadie 加权恢复）、以及工具的制度含义（它模拟的是哪种政策扩张）。<span class="marginnote">数字实例：若奖学金使大学入学率从 50% 涨到 58%，第一阶段就是 8 个百分点——Wald 比的分母是 0.08，被撬动的依从者约占人口的 8%。其余 92% 的人（always- 与 never-takers）对奖学金毫无反应；这个 LATE 估计得再准，也只替这 8% 的人说话。</span>视角再升一层：Heckman–Vytlacil 的<strong>边际处理效应</strong>曲线 \\(MTE(u)\\) 按不可观测的进入意愿排开效应，IV 估计量是这条曲线在工具决定的区间上加权；工具不同，权重不同——这就是「换工具换问题」的正式说法。单侧不依从（对照组拿不到处理）时没有单调性问题，encouragement 设计最干净；fuzzy RDD 是同一语言：估计对象是门槛邻域内 compliers 的效应，恰好把上一课的接口接上。弱工具的纪律不变：分母近零时 Wald 比连依从者效应都保不住，先过<a href="/econ/iv-weak-instruments">弱工具诊断</a>。</p>',9)),(n(),A(o,null,{default:r(()=>[i(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%B7%A5%E5%85%B7%20Z%20%E5%8F%98%E5%8A%A8%22%5D%20--%3E%20C%5B%22compliers%3A%20%E5%8F%AA%E5%9C%A8%E4%BB%96%E4%BB%AC%E8%BA%AB%E4%B8%8A%E5%8A%A8%22%5D%0A%20%20Z%20--%3E%20A%5B%22always-takers%3A%20%E4%B8%8D%E9%9A%8F%E5%B7%A5%E5%85%B7%E5%8A%A8%22%5D%0A%20%20Z%20--%3E%20N%5B%22never-takers%3A%20%E4%B8%8D%E9%9A%8F%E5%B7%A5%E5%85%B7%E5%8A%A8%22%5D%0A%20%20MON%7B%22monotonicity%20%E6%88%90%E7%AB%8B%3F%22%7D%20--%3E%7C%E6%98%AF%7C%20OK%5B%22defiers%20%E6%8E%92%E9%99%A4%22%5D%0A%20%20MON%20--%3E%7C%E5%90%A6%7C%20MIX%5B%22Wald%20%E6%AF%94%E6%98%AF%E7%AC%A6%E5%8F%B7%E4%B8%8D%E5%AE%9A%E7%9A%84%E6%B7%B7%E5%90%88%22%5D%0A%20%20C%20--%3E%20LATE%5B%22LATE%3A%20%E4%BE%9D%E4%BB%8E%E8%80%85%E5%B9%B3%E5%9D%87%E6%95%88%E5%BA%94%22%5D%0A%20%20MTE%5B%22MTE%20%E6%9B%B2%E7%BA%BF%22%5D%20--%3E%20W%5B%22%E4%B8%8D%E5%90%8C%E5%B7%A5%E5%85%B7%E4%B8%8D%E5%90%8C%E5%8A%A0%E6%9D%83%22%5D%0A%20%20W%20--%3E%20LATE%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,[E("机制是分层消去。Wald 比的分子 \\(\\mathrm{Cov}(Z,Y)\\) 里，always-takers 与 never-takers 的处理状态不随工具变，其结果变异被分母消去，剩下的分子只装着依从者的 \\(Y(1)-Y(0)\\)；分母装着依从者份额。IV 于是不是「更聪明的回归」，是把识别范围"),a("strong",null,"收缩"),E("到能被工具移动的那群人。政策含义随之改变：若目标政策改变的依从边际与工具不同（比如全国扩招撬动的是另一段入学分布），LATE 不能直接搬——搬的对象是 MTE 曲线的形状与依从者画像，不是单个数字。")],-1)),e[5]||(e[5]=a("p",null,"不这么做会错在哪：把 LATE 当 ATE 报，等于用边际学生的教育回报回答全人口的平均回报；不报第一阶段幅度，读者无法知道这个数覆盖了多少人、是谁。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"常见误区：初学者容易把 IV 结果写成「教育的回报率是 X%」。严格写法必须带限定语——「对被出生季度约束撬动的那部分边际学生」。这一步如果省了，后面拿这个数字去预测「全国扩招」的效果时，等于假设扩招撬动的也是同一批边际人，政策外推从结论句就开始错。")],-1)),(n(),A(o,null,{default:r(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUM%5B%22%E5%88%86%E5%AD%90%20Cov(Z%2CY)%22%5D%20--%3E%20A%5B%22always%20%2F%20never-takers%3A%20D%20%E4%B8%8D%E9%9A%8F%20Z%20%E5%8F%98%22%5D%0A%20%20A%20--%3E%20CANC%5B%22%E5%85%B6%E7%BB%93%E6%9E%9C%E5%8F%98%E5%BC%82%E8%A2%AB%E5%88%86%E6%AF%8D%E6%B6%88%E5%8E%BB%22%5D%0A%20%20CANC%20--%3E%20REST%5B%22%E5%88%86%E5%AD%90%E5%8F%AA%E5%89%A9%E4%BE%9D%E4%BB%8E%E8%80%85%E7%9A%84%20Y(1)-Y(0)%22%5D%0A%20%20DEN%5B%22%E5%88%86%E6%AF%8D%20Cov(Z%2CD)%22%5D%20--%3E%20SHARE%5B%22%E5%88%86%E6%AF%8D%20%3D%20%E4%BE%9D%E4%BB%8E%E8%80%85%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20REST%20--%3E%20LATE%5B%22Wald%20%E6%AF%94%20%3D%20%E4%BE%9D%E4%BB%8E%E8%80%85%E5%B9%B3%E5%9D%87%E6%95%88%E5%BA%94%22%5D%0A%20%20SHARE%20--%3E%20LATE%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p>上图回答的问题是 Wald 比凭什么「恰好」只剩依从者：分层图（上表）画出人口怎么被劈成四层，这张画出消去机制——两层不随工具动的人在分子分母里同步出现、相消，分子分母各留下一半 Wald 比，识别不是运气，是消去法的代数结果。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做 MTE 的结构估计与政策外推测度，那要更重的模型假设；一般均衡与市场规模效应不进 LATE 语言。多值处理、连续工具的 LATE 定义只标接口。排除约束在恰可识别下依然不可检验，本课给出的只是画像与机制故事的可信度清单，不是检验。弱工具与异质同时出现时，名义置信区间最先失效，纪律沿主干口径。</p><p>后课默认：IV 的结论句写「对依从者」，不写「对所有人」；下一课从设计源头处理依从——随机化实验的 ITT 与 TOT。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单调性排除 defiers 后，Wald 比识别依从者的平均效应。</li><li>LATE 工具特定；正式说法是 MTE 曲线上不同工具的不同加权。</li><li>依从者份额就是第一阶段；画像用 Abadie 加权恢复。</li><li>政策外搬运的是曲线与画像，不是单个 LATE。</li><li>出处：Imbens and Angrist, <em>Econometrica</em> 1994；Angrist, Imbens and Rubin, <em>JASA</em> 1996；Abadie, <em>J. Econometrics</em> 2003；Heckman and Vytlacil, <em>Econometrica</em> 2005。</li></ul>',6))])}const C=l(m,[["render",p]]);export{g as __pageData,C as default};
